#!/usr/bin/env node
// bpmn: {"file":"{{sourceBpmnPath}}","elements":[]}
//
// Claude Code SubagentStop / Stop / SessionEnd hook of the "{{workflow}}" workflow, generated by
// flowforge-generate (step 6b) from assets/templates/hook-cost-ledger-template.mjs. CLAUDE-ONLY.
//
// It only RECORDS: every finished API request of the session (main thread + subagents) is appended
// once to .claude/runs/{{workflow}}/ledger.jsonl as raw token counts. No prices, no grouping, no
// network. The FlowForge plugin's flowforge-cost reads the ledger together with
// .claude/hooks/{{workflow}}-cost-map.json and turns it into cost per BPMN element.
//
// It needs nothing from the hook payload but `transcript_path`, so it does not depend on the
// per-event fields. It is idempotent (a request is written once, keyed by requestId), so firing on
// several events is safe. It never fails the run: any problem goes to stderr and exits 0.
//
// Line shapes (one JSON object per line):
//   {kind:'request', sessionId, requestId, source, agentId, agentType, description, attributionSkill,
//    attributionMcpServer, attributionMcpTool, model, phase, final, chars, usage:{input,output,cacheRead,cacheWrite5m,cacheWrite1h,webSearch}}
//   {kind:'cost-state', sessionId, version, costState:{totalCostUSD, hasUnknownModelCost, modelUsage}}
//
// Smoke test (expect two lines, then none on a second run):
//   echo '{"transcript_path":"<session>.jsonl"}' | CLAUDE_PROJECT_DIR=/tmp/p node {{workflow}}-cost-ledger.mjs

import fs from 'node:fs'
import path from 'node:path'

const WORKFLOW = '{{workflow}}'

function* jsonLines(file) {
  for (const l of fs.readFileSync(file, 'utf8').split('\n')) {
    if (!l.trim()) continue
    try { yield JSON.parse(l) } catch { /* a half-written last line is picked up by the next event */ }
  }
}

function toUsage(u) {
  const cc = u.cache_creation
  return {
    input: u.input_tokens ?? 0,
    output: u.output_tokens ?? 0,
    cacheRead: u.cache_read_input_tokens ?? 0,
    cacheWrite5m: cc ? (cc.ephemeral_5m_input_tokens ?? 0) : (u.cache_creation_input_tokens ?? 0),
    cacheWrite1h: cc?.ephemeral_1h_input_tokens ?? 0,
    webSearch: u.server_tool_use?.web_search_requests ?? 0,
  }
}

// One API request spans several lines; only the last carries the final output_tokens.
const chars = new Map() // requestId -> length of the content it produced (a weight for completing output tokens later)

function readThread(file, meta, requests) {
  for (const e of jsonLines(file)) {
    if (e.type !== 'assistant' || !e.requestId || !e.message?.usage || !e.message.model) continue
    if (e.message.model === '<synthetic>') continue
    const usage = toUsage(e.message.usage)
    const cur = requests.get(e.requestId)
    if (!cur || usage.output >= cur.usage.output) {
      requests.set(e.requestId, {
        kind: 'request', requestId: e.requestId, source: meta.source, agentId: meta.agentId ?? null,
        agentType: meta.agentType ?? null, description: meta.description ?? null, phase: meta.phase ?? null,
        attributionSkill: e.attributionSkill ?? null, attributionMcpServer: e.attributionMcpServer ?? null,
        attributionMcpTool: e.attributionMcpTool ?? null, model: e.message.model, stopReason: e.message.stop_reason ?? null, usage,
      })
    }
    chars.set(e.requestId, (chars.get(e.requestId) ?? 0) + JSON.stringify(e.message.content ?? '').length)
  }
}

function agentTranscripts(dir) {
  if (!fs.existsSync(dir)) return []
  const out = []
  for (const e of fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
    const p = path.join(dir, e.name)
    if (e.isDirectory()) out.push(...agentTranscripts(p))
    else if (/^agent-.*\.jsonl$/.test(e.name)) out.push(p)
  }
  return out
}

// Sleeps without spinning; a held lock only ever lasts for one append.
const sleep = (ms) => Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms)

function main() {
  const input = JSON.parse(fs.readFileSync(0, 'utf8'))
  let transcript = input.transcript_path
  if (!transcript || !fs.existsSync(transcript)) return
  // SubagentStop may hand over the subagent's own transcript: <session>/subagents/agent-<id>.jsonl
  const sub = transcript.match(/^(.*)[\\/]([^\\/]+)[\\/]subagents[\\/]agent-[^\\/]+\.jsonl$/)
  if (sub) transcript = path.join(sub[1], `${sub[2]}.jsonl`)
  if (!fs.existsSync(transcript)) return
  const sessionId = path.basename(transcript, '.jsonl')

  const requests = new Map()
  readThread(transcript, { source: 'main' }, requests)
  // agents of the Workflow tool sit deeper: subagents/workflows/<run>/agent-<id>.jsonl
  for (const file of agentTranscripts(path.join(path.dirname(transcript), sessionId, 'subagents'))) {
    const agentId = path.basename(file).slice('agent-'.length, -'.jsonl'.length)
    let m = {}
    try { m = JSON.parse(fs.readFileSync(path.join(path.dirname(file), `agent-${agentId}.meta.json`), 'utf8')) } catch { /* no meta */ }
    readThread(file, { source: 'subagent', agentId, agentType: m.agentType, description: m.description, phase: m.workflowPhase }, requests)
  }
  let costState = null
  let version = null
  for (const e of jsonLines(transcript)) {
    if (e.type === 'cost-state') costState = e
    if (!version && e.version) version = e.version
  }

  const dir = path.join(process.env.CLAUDE_PROJECT_DIR || input.cwd || process.cwd(), '.claude', 'runs', WORKFLOW)
  fs.mkdirSync(dir, { recursive: true })
  const ledger = path.join(dir, 'ledger.jsonl')
  const lock = path.join(dir, '.ledger.lock')
  let fd = -1
  for (let i = 0; i < 40 && fd < 0; i++) {
    try { fd = fs.openSync(lock, 'wx') } catch { sleep(50) }
    if (fd < 0 && i === 20) { try { if (Date.now() - fs.statSync(lock).mtimeMs > 10000) fs.unlinkSync(lock) } catch { /* raced */ } }
  }
  if (fd < 0) return process.stderr.write(`${WORKFLOW} cost ledger: could not lock ${ledger}, skipped\n`)
  try {
    const seen = new Map() // requestId -> how it was last written
    let lastCostState = null
    if (fs.existsSync(ledger)) {
      for (const e of jsonLines(ledger)) {
        if (e.sessionId !== sessionId) continue
        if (e.kind === 'request') seen.set(e.requestId, `${e.usage?.output}|${e.final ?? true}`)
        if (e.kind === 'cost-state') lastCostState = JSON.stringify(e.costState)
      }
    }
    // A request is (re)written when it is new or has improved. Agents of the Workflow tool never get a final
    // output_tokens written back, so their rows stay final:false; the cost report completes them.
    const lines = []
    for (const r of requests.values()) {
      const sig = `${r.usage.output}|${!!r.stopReason}`
      if (seen.get(r.requestId) === sig) continue
      const { stopReason, ...row } = r
      lines.push({ ...row, final: !!stopReason, chars: chars.get(r.requestId) ?? 0, sessionId })
    }
    if (costState) {
      const cs = { totalCostUSD: costState.totalCostUSD, hasUnknownModelCost: !!costState.hasUnknownModelCost, modelUsage: costState.modelUsage }
      if (JSON.stringify(cs) !== lastCostState) lines.push({ kind: 'cost-state', sessionId, version, costState: cs })
    }
    if (lines.length) fs.appendFileSync(ledger, lines.map((l) => JSON.stringify(l)).join('\n') + '\n')
  } finally {
    fs.closeSync(fd)
    try { fs.unlinkSync(lock) } catch { /* already gone */ }
  }
}

try {
  main()
} catch (e) {
  process.stderr.write(`${WORKFLOW} cost ledger: ${e.message}\n`)
}
process.exit(0)

/*
Authoring notes for whoever fills this template (flowforge-generate step 6b; the deterministic
install-cost-ledger.mjs does all of this, prefer it):
- Fill only {{workflow}} and {{sourceBpmnPath}}. The header's `elements` stays [] — the hook belongs to
  the whole workflow, like the context hooks it claims no generatedPaths entry.
- Node built-ins only, no prices, no network. Keep readThread in step with
  flowforge-cost/scripts/read-usage.mjs (the cost tests run both against one fixture).
- Register on SubagentStop, Stop and SessionEnd in .claude/settings.json (no matcher).
*/
